import{_ as t,o,c as r,ag as a}from"./chunks/framework.QfQ7DfGu.js";const g=JSON.parse('{"title":"LoongArch教学OS","description":"","frontmatter":{"title":"LoongArch教学OS","outline":"deep"},"headers":[],"relativePath":"os/os-edu.md","filePath":"os/os-edu.md"}'),l={name:"os/os-edu.md"};function n(c,e,p,s,i,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="loongarch教学os" tabindex="-1">LoongArch教学OS <a class="header-anchor" href="#loongarch教学os" aria-label="Permalink to &quot;LoongArch教学OS&quot;">​</a></h1><p>此处收集LoongArch教学OS及其对应课程，信息汇总如下：</p><table tabindex="0"><thead><tr><th style="text-align:center;">课程</th><th style="text-align:center;">名称</th><th style="text-align:center;">链接</th></tr></thead><tbody><tr><td style="text-align:center;">操作系统设计与实现：基于MaQue教学操作系统</td><td style="text-align:center;">MaQue</td><td style="text-align:center;"><a href="https://github.com/LoongsonLab/maqueos/" target="_blank" rel="noreferrer">仓库地址</a></td></tr><tr><td style="text-align:center;">操作系统原型-xv6实验与分析</td><td style="text-align:center;">xv6</td><td style="text-align:center;"><a href="https://github.com/LoongsonLab/xv6-loongarch-exp" target="_blank" rel="noreferrer">仓库地址</a></td></tr><tr><td style="text-align:center;">操作系统实验：基于ucore-loongarch教学操作系统</td><td style="text-align:center;">ucore</td><td style="text-align:center;"><a href="https://github.com/LoongsonLab/ucore-loongarch64" target="_blank" rel="noreferrer">仓库地址</a></td></tr><tr><td style="text-align:center;">操作系统实验：基于rcore-loongarch教学操作系统</td><td style="text-align:center;">rcore</td><td style="text-align:center;"><a href="https://github.com/Godones/rCoreloongArch" target="_blank" rel="noreferrer">仓库地址</a></td></tr><tr><td style="text-align:center;">操作系统内核构建实践实例NPUcore</td><td style="text-align:center;">NPUcore</td><td style="text-align:center;"><a href="https://github.com/LoongsonLab/npucore-loongarch64" target="_blank" rel="noreferrer">仓库地址</a></td></tr><tr><td style="text-align:center;">NJUos：计算机操作系统</td><td style="text-align:center;">NJUos</td><td style="text-align:center;"><a href="https://github.com/bzy666-666/NJU-OS-loongarch" target="_blank" rel="noreferrer">仓库地址</a></td></tr><tr><td style="text-align:center;">MOS：操作系统课程实验</td><td style="text-align:center;">MOS</td><td style="text-align:center;"><a href="https://github.com/chhss17/buaa_mos_la64" target="_blank" rel="noreferrer">仓库地址</a></td></tr></tbody></table><h2 id="操作系统设计与实现-基于maque教学操作系统" tabindex="-1">操作系统设计与实现：基于MaQue教学操作系统 <a class="header-anchor" href="#操作系统设计与实现-基于maque教学操作系统" aria-label="Permalink to &quot;操作系统设计与实现：基于MaQue教学操作系统&quot;">​</a></h2><ol><li><p>课程简介</p><p><code>MaQueOS</code>是一个开源的基于<em><strong>LoongArch</strong></em>架构的教学版操作系统。作为一个教学版操作系统，MaQueOS的代码虽然只有1000多行，但是它实现了操作系统最核心的功能子系统：进程管理、内存管理、文件系统、中断管理和外设驱动，并为应用程序提供了16个系统调用接口。</p><p>详细介绍可查看<code>maqueos/README.md</code>。</p><p>点击查看<a href="https://www.bilibili.com/video/BV1EH4y1c7WX/?share_source=copy_web" target="_blank" rel="noreferrer">在线课程</a>。</p><p><code>doc/maqueos</code>目录下包含相应教材与实验指导书。</p></li><li><p>使用说明</p><p>运行教程可查看<code>maqueos/README.md#二、编译运行调试</code>，或参考实验指导书。</p></li><li><p>更新说明</p><p><strong>该版本目前支持qemu-9.2及以上版本运行</strong>。</p><p>仓库地址<a href="https://github.com/LoongsonLab/maqueos/" target="_blank" rel="noreferrer">在这里</a></p></li></ol><h2 id="操作系统原型-xv6实验与分析" tabindex="-1">操作系统原型-xv6实验与分析 <a class="header-anchor" href="#操作系统原型-xv6实验与分析" aria-label="Permalink to &quot;操作系统原型-xv6实验与分析&quot;">​</a></h2><ol><li><p>课程简介</p><p><code>xv6</code>是麻省理工的一个教学操作系统，是 Dennis Ritchie 和 Ken Thompson 的 Unix 的重新实现版本 6 (v6)。 被广泛应用于操作系统教学课程。</p><p>本项目本项目将<code>xv6</code>移植到<em><strong>LoongArch</strong></em>架构上。</p><p>详细介绍可查看<code>xv6-loongarch-exp/README.md</code>。</p><p><code>doc/xv6-loongarch-exp</code>目录下包含相应实验指导书。</p></li><li><p>使用说明</p><p>运行可查看<code>xv6-loongarch-exp/README.md#更新</code>，或查看实验指导书。</p></li><li><p>更新说明</p><p><strong>该版本目前支持qemu-9.2及以上版本运行</strong>。</p><p>仓库地址<a href="https://github.com/LoongsonLab/xv6-loongarch-exp" target="_blank" rel="noreferrer">在这里</a></p></li></ol><h2 id="操作系统实验ucore" tabindex="-1">操作系统实验ucore <a class="header-anchor" href="#操作系统实验ucore" aria-label="Permalink to &quot;操作系统实验ucore&quot;">​</a></h2><ol><li><p>课程简介</p><p>本课程为重庆大学操作系统实验，其基于<code>ucore-thumips</code>，移植到<em><strong>Loongarch</strong></em>上。</p><p>详细介绍可查看<code>ucore-loongarch64/README.md</code>。</p><p>点击查看<a href="https://space.bilibili.com/12553542/lists" target="_blank" rel="noreferrer">在线课程</a>。</p><p>本课程提供在线指导手册，请<a href="https://cyyself.github.io/ucore_la32_docs/" target="_blank" rel="noreferrer">点击查看</a>.</p></li><li><p>使用说明</p><p>运行教程可查看<code>ucore-loongarch64/README.md#使用教程</code>。</p></li><li><p>更新说明</p><p><strong>该版本目前支持qemu-9.2及以上版本运行</strong>。</p><p>仓库地址<a href="https://github.com/LoongsonLab/ucore-loongarch64" target="_blank" rel="noreferrer">在这里</a></p></li></ol><h2 id="操作系统内核构建实践实例npucore" tabindex="-1">操作系统内核构建实践实例NPUcore <a class="header-anchor" href="#操作系统内核构建实践实例npucore" aria-label="Permalink to &quot;操作系统内核构建实践实例NPUcore&quot;">​</a></h2><ol><li><p>课程简介</p><p><code>NPUcore</code>是<strong>西北工业大学</strong>的操作系统内核构建实践型教学操作系统。目前<code>NPUcore</code>具有内存管理、进程管理、文件系统、网络核心功能，支持龙芯国产自主<em><strong>LoongArch</strong></em>架构。</p><p>详细介绍可查看<code>npucore-loongarch64/README.md</code>。</p></li><li><p>使用说明</p><p>运行教程可查看<code>npucore-loongarch64/README.md#环境配置</code>。</p></li><li><p>更新说明</p><p><strong>该版本目前支持qemu-9.2及以上版本运行</strong>。</p><p>仓库地址<a href="https://github.com/LoongsonLab/npucore-loongarch64" target="_blank" rel="noreferrer">在这里</a></p></li></ol><h2 id="操作系统实验-基于rcore-loongarch教学操作系统" tabindex="-1">操作系统实验：基于rcore-loongarch教学操作系统 <a class="header-anchor" href="#操作系统实验-基于rcore-loongarch教学操作系统" aria-label="Permalink to &quot;操作系统实验：基于rcore-loongarch教学操作系统&quot;">​</a></h2><ol><li><p>课程简介</p><p>rCore为清华大学操作系统课程使用的教学系统，是基于ucore系统，使用rust语言重新实现的版本。</p></li><li><p>使用说明</p><p>运行教程可查看<code>rcore-loongarch64/README.md</code>。</p></li><li><p>更新说明</p><p><strong>该版本目前支持qemu-9.2及以上版本运行</strong>。</p><p>仓库地址<a href="https://github.com/Godones/rCoreloongArch" target="_blank" rel="noreferrer">在这里</a></p></li></ol><h2 id="npucore-rust-操作系统内核构建实践实例" tabindex="-1">NPUcore-rust：操作系统内核构建实践实例 <a class="header-anchor" href="#npucore-rust-操作系统内核构建实践实例" aria-label="Permalink to &quot;NPUcore-rust：操作系统内核构建实践实例&quot;">​</a></h2><ol><li><p>课程简介</p><p><code>NPUcore</code>是西北工业大学的操作系统内核构建实践型教学操作系统。目前<code>NPUcore</code>具有内存管理、进程管理、文件系统、网络核心功能，支持龙芯国产自主<em><strong>LoongArch</strong></em>架构。该版本为使用rust语言重新实现版本。</p></li><li><p>使用说明</p><p>暂无。</p></li><li><p>更新说明</p><p>处于调试阶段。</p></li></ol><h2 id="mos-操作系统课程实验" tabindex="-1">MOS：操作系统课程实验 <a class="header-anchor" href="#mos-操作系统课程实验" aria-label="Permalink to &quot;MOS：操作系统课程实验&quot;">​</a></h2><ol><li><p>课程简介</p><p><code>MOS</code>为北京航空航天大学计算机学院《操作系统》课程实验成果，为基于<em><strong>Loongarch</strong></em>架构的简易操作系统实现，包含内存管理、进程调度、文件系统、进程间通信等核心功能。</p></li><li><p>使用说明</p><p>暂无。</p></li><li><p>更新说明</p><p>处于调试阶段。</p><p>仓库地址<a href="https://github.com/chhss17/buaa_mos_la64" target="_blank" rel="noreferrer">在这里</a></p></li></ol><h2 id="njuos-计算机操作系统" tabindex="-1">NJUos：计算机操作系统 <a class="header-anchor" href="#njuos-计算机操作系统" aria-label="Permalink to &quot;NJUos：计算机操作系统&quot;">​</a></h2><ol><li><p>课程简介</p><p><code>NJUos</code>为南京大学操作系统实验。实验要求深入理解操作系统概念、原理及实践操作。实验中探索操作系统的核心功能，包括进程管理、内存管理、文件系统和I/O设备控制等。具体实验内容涵盖了进程创建、撤销、调度、同步与通信、内存分配与回收、文件系统设计、I/O设备的驱动编写和中断处理等。</p></li><li><p>使用说明</p><p>暂无。</p></li><li><p>更新说明</p><p>处于调试阶段</p><p>仓库地址<a href="https://github.com/bzy666-666/NJU-OS-loongarch" target="_blank" rel="noreferrer">在这里</a></p></li></ol>',19)])])}const u=t(l,[["render",n]]);export{g as __pageData,u as default};
